"use strict";
import { Check } from "react-feather";
import { Button } from "rebass";
import { Flex, Text, useSporeColors } from "ui/src";
import { useAddLiquidityContext } from "../ContextProvider";
export default function DepositAmoutAndEdit({ type }) {
  const { setStakeStep, setWithdrawStep, setAddLiquidityStep } = useAddLiquidityContext();
  const colors = useSporeColors();
  const handleStep = () => {
    if (type === "Deposit") {
      setAddLiquidityStep("step-1");
    } else if (type === "Stake") {
      setStakeStep("step-1");
    } else {
      setWithdrawStep("step-1");
    }
  };
  return <Flex
    row
    p={"$spacing24"}
    $sm={{ p: "$spacing16" }}
    borderRadius={"$rounded12"}
    backgroundColor={"$surface2"}
    justifyContent="space-between"
    gap={"$gap12"}
    alignItems="center"
  >
      <Flex row gap={"$gap8"} alignItems="center">
        <Flex row centered height={20} width={20} backgroundColor={"$accent1"} borderRadius={"$roundedFull"}>
          <Check size={16} color={colors.surface1.val} />
        </Flex>
        <Text variant="buttonLabel3">Deposit amount</Text>
      </Flex>
      <Flex row gap={"$gap12"} alignItems="center">
        <Text variant="body3">~$54.58673</Text>
        <Button className="button-clear" padding={0} onClick={handleStep}>
          <Text
    variant="buttonLabel3"
    backgroundColor={"$surface3"}
    px={"$padding12"}
    py={"$padding8"}
    borderRadius={"$roundedFull"}
    cursor="pointer"
    onPress={handleStep}
  >
            Edit
          </Text>
        </Button>
      </Flex>
    </Flex>;
}
